uv4 = uv2*.1 +tstars*vec2(0.02, 1.0 ) + 0.01*gnd;
//uv4 = uv4.yx;
smask = texture(sampler_pw_noise_lq,uv4)>.8;
//stars += 1.0 / length(abs(fract(uv4 * 256.0+ rip*0.1)-.5))*smask;
ret.b += (1.0 - uv.y)*0.2;
ret += gnd*gmask*(.15+stars*stars*0.01)*abo;
// Dioden
