uv1 = ((uv0-0.5)-rs * 0.0-vec2(q1,-q2))*uAspect.xy+dz * 4.0;
bl += .07/length(uv1)*sat(1.0 - gm0);;
uv1 = ((uv0-0.5)-rs * 0.0-vec2(q10,-q12))*uAspect.xy+gnd*0.1+dz * 2.0+rip*.0;
bl += pow(.07/length(uv1), 2.0 )*gmask;
ret += q31*bl*(1.0 + audioMidSmooth / 2.0)*sat(1.0 - smoke.x * 32.0*rand_preset.x)*roam_cos;
ret = vec3( 1.0 ) - exp(-ret*1.8);
  fragColor = vec4(ret, 1.0);
}

