ret += 0.00015/pow(length(uv1), 2.0 )*audioHigh;
uv1 = ((uv0-0.5)-vec2(q5,-q6))*uAspect.xy+rip*.02;
ret += 0.0007/pow(length(uv1+dref), 2.0 )*abo*audioHigh*gnd*gmask;
